<script>const mode=document.getElementById('paymentMode'),sync=()=>{document.querySelectorAll('[data-ref]').forEach(x=>x.classList.add('hidden'));let m=mode.value;if(m==='upi'){document.querySelector('[data-ref=upi]').classList.remove('hidden');document.querySelector('[data-ref=transaction]').classList.remove('hidden')}if(m==='bank_transfer'){document.querySelector('[data-ref=bank]').classList.remove('hidden');document.querySelector('[data-ref=transaction]').classList.remove('hidden')}if(m==='cheque')document.querySelectorAll('[data-ref=cheque]').forEach(x=>x.classList.remove('hidden'));if(m==='other')document.querySelector('[data-ref=transaction]').classList.remove('hidden')};mode.onchange=sync;sync();</script>@endsection
